-- GEHLEE_LOADER_BEGIN
do
    local loader = {}
    loader.Paths = {"Gehlee_Hub_Stability_v10.lua", "Gehlee_Hub.lua", "GehleeHub/Gehlee_Hub.lua"}
    function loader.Source()
        if type(readfile) ~= "function" then
            return nil, "This executor cannot read a local script. Run Gehlee Hub again after teleporting."
        end
        for _, path in ipairs(loader.Paths) do
            local ok, source = pcall(readfile, path)
            if ok and type(source) == "string" and source:sub(1, 33) == "-- GEHLEE_HUB_STANDALONE_BUILD_1\n" then
                local compiled, chunk = pcall(loadstring, source)
                if compiled and type(chunk) == "function" then
                    return source, path
                end
            end
        end
        return nil, "Save Gehlee_Hub.lua in your executor's workspace to enable automatic reload."
    end
    loader.Boot = [==[
if game:GetAttribute("GehleeBootQueued") then return end
repeat task.wait(0.5) until game:IsLoaded()
if game:GetAttribute("GehleeBootQueued") then return end
local paths = {"Gehlee_Hub_Stability_v10.lua", "Gehlee_Hub.lua", "GehleeHub/Gehlee_Hub.lua"}
for _, path in ipairs(paths) do
    if type(readfile) == "function" then
        local ok, source = pcall(readfile, path)
        if ok and type(source) == "string" and source:sub(1, 33) == "-- GEHLEE_HUB_STANDALONE_BUILD_1\n" then
            local compiled, chunk = pcall(loadstring, source)
            if compiled and type(chunk) == "function" then
                if game:GetAttribute("GehleeBootQueued") then return end
                game:SetAttribute("GehleeBootQueued", true)
                local ran, err = pcall(chunk)
                if not ran then
                    game:SetAttribute("GehleeBootQueued", nil)
                    warn("[Gehlee Hub] Reload failed: " .. tostring(err))
                end
                return
            end
        end
    end
end
warn("[Gehlee Hub] Save Gehlee_Hub.lua in the executor workspace, or run it again manually.")
]==]
    loader.AutoBoot = [==[
if type(readfile) ~= "function" then return end
local enabled, state = pcall(readfile, "Gehlee_AutoExecute.txt")
if not enabled or state ~= "1" then return end
]==] .. loader.Boot
    function loader.Queue(persist)
        local source, note = loader.Source()
        if not source then return false, note end
        local code = loader.Boot
        if persist then
            if type(writefile) ~= "function" then
                return false, "Automatic reload needs file-writing support so it can be turned off safely."
            end
            local ok, result = pcall(writefile, "Gehlee_AutoExecute.txt", "1")
            if not ok or result == false then return false, "Could not save the automatic reload setting." end
            code = loader.AutoBoot
        end
        local queued = false
        local queue = queue_on_teleport or queueonteleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
        if type(queue) == "function" then
            local ok, result = pcall(queue, code)
            queued = ok and result ~= false
        end
        local saved = false
        if persist and type(writefile) == "function" and type(isfolder) == "function" then
            for _, directory in ipairs({"autoexec", "autoexecute"}) do
                local ok, exists = pcall(isfolder, directory)
                if ok and exists then
                    local wrote, result = pcall(writefile, directory .. "/Gehlee_Hub_Boot.lua", code)
                    saved = (wrote and result ~= false) or saved
                end
            end
        end
        if queued or saved then return true end
        return false, "This executor has no working teleport queue or auto-execute folder. Reload the script manually."
    end
    function loader.Clear()
        local cancelled = false
        if type(writefile) == "function" then
            local ok, result = pcall(writefile, "Gehlee_AutoExecute.txt", "0")
            cancelled = ok and result ~= false
        end
        for _, directory in ipairs({"autoexec", "autoexecute"}) do
            local path = directory .. "/Gehlee_Hub_Boot.lua"
            local removed = false
            if type(delfile) == "function" then
                local ok, result = pcall(delfile, path)
                removed = ok and result ~= false
            end
            if not removed and type(writefile) == "function" and type(isfile) == "function" then
                local ok, exists = pcall(isfile, path)
                if ok and exists then pcall(writefile, path, "") end
            end
        end
        return cancelled
    end
    genv.GehleeLoader = loader
end
-- GEHLEE_LOADER_END

