local allConnections = {}
local resizeDebounceTable = {}
local heartbeatCallbacks = {}
local heartbeatConnection = nil

local function trackConnection(conn, name)
	if not conn then
		return nil
	end
	table.insert(allConnections, { conn = conn, name = name or "unnamed" })
	return conn
end

local function disconnectAll()
	for _, entry in ipairs(allConnections) do
		if entry.conn then
			pcall(function()
				entry.conn:Disconnect()
			end)
		end
	end
	allConnections = {}
end

local function registerHeartbeat(name, callback)
	if not name or not callback then
		return
	end
	heartbeatCallbacks[name] = callback
	if not heartbeatConnection then
		heartbeatConnection = game:GetService("RunService").Heartbeat:Connect(function(dt)
			for _, cb in pairs(heartbeatCallbacks) do
				if cb then
					pcall(function()
						cb(dt)
					end)
				end
			end
		end)
	end
end

local function unregisterHeartbeat(name)
	heartbeatCallbacks[name] = nil
	if next(heartbeatCallbacks) == nil and heartbeatConnection then
		heartbeatConnection:Disconnect()
		heartbeatConnection = nil
	end
end

local function debounceResize(key, callback, delay)
	delay = delay or 0.1
	if resizeDebounceTable[key] then
		task.cancel(resizeDebounceTable[key])
	end
	resizeDebounceTable[key] = task.delay(delay, function()
		pcall(function()
			callback()
		end)
		resizeDebounceTable[key] = nil
	end)
end

local config = { gamefolder = nil, autoloadfile = nil, data = {}, elements = {}, version = nil, current = nil, loaded = false }

local metakeys = {
	["Input_Config Name"] = true,
	["Input_External Config"] = true,
}

local function packconfig(data)
	local out = {}
	for key, value in pairs(data or {}) do
		local keep = not metakeys[key]
        -- GEHLEE_V7_PERSIST_EXPLICIT_FALSE
        if value == nil then
            keep = false
        elseif value == false then
            local element = config.elements[key]
            keep = keep and element ~= nil and element.DefaultWhenMissing == true
		elseif type(value) == "string" and value:gsub("%s+", "") == "" then
			keep = false
		elseif type(value) == "table" and next(value) == nil then
			keep = false
		end
		if keep then
			out[key] = value
		end
	end
	return out
end

local function missingdefault(key, element)
	if key:match("^Toggle_") then
        -- GEHLEE_V7_MISSING_TOGGLE_DEFAULT
        if element.DefaultWhenMissing == true then return element.DefaultValue == true end
		return false
	elseif key:match("^Input_") then
		return ""
	elseif key:match("^Dropdown_") then
		if type(element.Value) == "table" then
			return {}
		end
		return nil
	end
	return nil
end
-- All surfaces use the same executor-compatible root, including recovery UI.
-- Keep references for cleanup: a hidden-root GUI is not a CoreGui child.
local ownedScreenGuis = {}
local GUI_ORDER = 10000
local function guiRoots()
	local roots = {}
	local function add(root)
		local ok, valid = pcall(function()
			return typeof(root) == "Instance" and (root:IsA("Folder") or root:IsA("CoreGui") or root:IsA("PlayerGui"))
		end)
		if ok and valid and not table.find(roots, root) then roots[#roots + 1] = root end
	end
	if type(gethui) == "function" then
		local ok, root = pcall(gethui)
		if ok then add(root) end
	end
	add(sv.coregui)
	local ok, playerGui = pcall(function()
		local player = sv.plrs.LocalPlayer
		return player and player:FindFirstChildOfClass("PlayerGui")
	end)
	if ok then add(playerGui) end
	return roots
end

local function mountGui(gui)
	local ok, valid = pcall(function() return typeof(gui) == "Instance" and gui:IsA("ScreenGui") end)
	if not ok or not valid then return false, "Expected a ScreenGui." end
	elevate()
	local protect = (type(syn) == "table" and type(syn.protect_gui) == "function" and syn.protect_gui)
		or (type(protect_gui) == "function" and protect_gui)
	if protect then pcall(protect, gui) end
	local lastError = "No available GUI root."
	for _, root in ipairs(guiRoots()) do
		local mounted, reason = pcall(function()
			gui.Parent = root
			gui.Enabled = true
		end)
		if mounted and gui.Parent == root then return root end
		lastError = tostring(reason or "GUI root rejected the window.")
	end
	return false, lastError
end

local function createScreenGui(name, displayOrder)
	local gui = Instance.new("ScreenGui")
	gui.Name = name
	gui.Enabled = true
	gui.ResetOnSpawn = false
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.DisplayOrder = displayOrder or GUI_ORDER
	local root, reason = mountGui(gui)
	if not root then
		gui:Destroy()
		error("[Gehlee Hub] Cannot mount the interface: " .. tostring(reason))
	end
	ownedScreenGuis[gui] = true
	return gui
end

