	function guifunc:ToggleUI()
		if windowDestroyed then return false, "This window was closed." end
		if self.ToggleGui then
			ownedScreenGuis[self.ToggleGui] = nil
			pcall(function() self.ToggleGui:Destroy() end)
		end
		local screengui = createScreenGui("GehleeToggleUIButton", GUI_ORDER + 1)
		guifunc.ToggleGui = screengui

		local imageSize = math.clamp(tonumber(guiconfig.ImageSize) or 56, 36, 96)
		local mainbutton = instance.frame(screengui)
		mainbutton.Name = "ReopenButton"
