		stroke.Thickness = 2

		local icon = instance.imagelabel(mainbutton)
		icon.Name = "ToggleIcon"
		icon.Position = UDim2.new(0, 4, 0, 4)
		icon.Size = UDim2.new(1, -8, 0, imageSize - 8)
		icon.BackgroundTransparency = 1
		icon.Image = "rbxassetid://118365640294748"
		icon.ScaleType = Enum.ScaleType.Crop
		local iconCorner = instance.uicorner(icon)
		iconCorner.CornerRadius = UDim.new(0, 6)

		local button = instance.textbutton(mainbutton)
		button.Name = "ToggleButton"
		button.Size = UDim2.new(1, 0, 1, 0)
		button.BackgroundTransparency = 1
		button.Text = ""
		guifunc.ToggleButton = button

		-- Text and a solid backing remain visible when Roblox cannot load the asset.
		local label = instance.textlabel(button)
		label.Name = "ReopenLabel"
		label.Position = UDim2.new(0, 0, 1, -20)
		label.Size = UDim2.new(1, 0, 0, 18)
		label.BackgroundColor3 = Color3.fromRGB(103, 48, 166)
		label.BackgroundTransparency = 0
		label.BorderSizePixel = 0
		label.Font = Enum.Font.GothamBold
		label.Text = "GEHLEE"
		label.TextSize = 10
		label.TextColor3 = Color3.fromRGB(255, 255, 255)
		label.TextTransparency = 0

		local dragging, suppressActivation = false, false
		local activeInput, dragstart, startpos
		local function clampToggle(position)
			local viewport = viewportSize()
			local x = position.X.Scale * viewport.X + position.X.Offset
			local y = position.Y.Scale * viewport.Y + position.Y.Offset
			return UDim2.new(0, math.clamp(x, 12, math.max(12, viewport.X - mainbutton.Size.X.Offset - 12)),
				0, math.clamp(y, 12, math.max(12, viewport.Y - mainbutton.Size.Y.Offset - 48)))
		end
		mainbutton.Position = clampToggle(mainbutton.Position)

		trackConnection(button.Activated:Connect(function()
			if suppressActivation then suppressActivation = false; return end
			guifunc:SetVisible(not (gehleeui.Parent ~= nil and gehleeui.Enabled and dropshadowholder.Visible))
		end), "togglebutton.activate")
		trackConnection(button.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging, suppressActivation = true, false
				activeInput, dragstart, startpos = input, input.Position, mainbutton.Position
			end
		end), "togglebutton.begin")
		trackConnection(sv.uis.InputChanged:Connect(function(input)
			if not dragging then return end
			local mouseMove = activeInput.UserInputType == Enum.UserInputType.MouseButton1
				and input.UserInputType == Enum.UserInputType.MouseMovement
			if input ~= activeInput and not mouseMove then return end
			local delta = input.Position - dragstart
			if math.abs(delta.X) > 6 or math.abs(delta.Y) > 6 then suppressActivation = true end
			if suppressActivation then
				mainbutton.Position = clampToggle(UDim2.new(startpos.X.Scale, startpos.X.Offset + delta.X,
					startpos.Y.Scale, startpos.Y.Offset + delta.Y))
			end
		end), "togglebutton.drag")
		trackConnection(sv.uis.InputEnded:Connect(function(input)
			if input == activeInput then dragging, activeInput = false, nil end
		end), "togglebutton.end")
		trackConnection(sv.uis.WindowFocusReleased:Connect(function()
			dragging, activeInput = false, nil
		end), "togglebutton.focusrelease")
		local camera = workspace.CurrentCamera
		if camera then
			trackConnection(camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
				mainbutton.Position = clampToggle(mainbutton.Position)
			end), "togglebutton.viewport")
		end
		return screengui
	end

	guifunc:ToggleUI()
	guifunc:Show()

	local tabs = { Gui = gehleeui, ToggleGui = guifunc.ToggleGui, ToggleButton = guifunc.ToggleButton }

    -- Compatibility with current hub controls, using the native window.
    function tabs:Alive() return gehleeui.Parent ~= nil and not GehleeUI.Unloaded end
    function tabs:GetTheme() return table.clone(theme) end
    function tabs:Show()
        local shown, reason = guifunc:Show()
        return shown and self or false, reason
    end
    function tabs:SetVisible(visible)
        local shown, reason = guifunc:SetVisible(visible)
        return shown and self or false, reason
    end
    function tabs:DestroyGui() return guifunc:DestroyGui() end
    function tabs:SaveConfig(name)
        name = tostring(name or "")
        if name == "" or #name > 80 or not name:match("^[%w_%- ]+$") then return false, "Use letters, numbers, spaces, - or _ for the profile name." end
        local ok, saved = pcall(config.save, config, name)
        if not ok then return false, tostring(saved) end
        return saved == true, saved == true and ("Saved " .. name) or "Profile storage is unavailable."
    end
    function tabs:LoadConfig(name)
        name = tostring(name or "")
        if name == "" or #name > 80 or not name:match("^[%w_%- ]+$") then return false, "Invalid profile name." end
        local ok, loaded = pcall(config.load, config, name)
        if not ok then return false, tostring(loaded) end
        return loaded == true, loaded == true and ("Loaded " .. name) or "Profile missing, unreadable, or incompatible."
    end
    function tabs:SetHeaderChips(chips)
        local text = {}
        for _, chip in ipairs(type(chips) == "table" and chips or {}) do
            if type(chip) == "table" then text[#text + 1] = tostring(chip.Text or "") end
        end
        textlabel.Size = UDim2.new(1, -100, 0, 16)
        textlabel.Position = UDim2.new(0, 10, 0, 3)
        textlabel1.Size = UDim2.new(1, -100, 0, 13)
        textlabel1.Position = UDim2.new(0, 10, 0, 21)
        textlabel1.TextSize = 10
        textlabel1.TextTruncate = Enum.TextTruncate.AtEnd
        textlabel1.Text = table.concat(text, "  ·  ")
    end
