            function items:AddPriorityList(options)
                options = options or {}
                local root, title = compatFrame("PriorityList", options)
                local description = compatLabel(root, "Description", options.Content or "", 28, 11, false)
                description.TextWrapped = true
                description.TextTruncate = Enum.TextTruncate.None
                local empty = compatLabel(root, "Empty", options.EmptyText or "No tasks enabled.", 50, 11, false)
                local control = {Frame = root, Rows = {}, Value = {}, DefaultValue = {}, _items = {}, _order = {}}
                local key = keyfor("Priority_", options)
                for _, item in ipairs(type(options.Items) == "table" and options.Items or {}) do
                    if type(item) == "table" and (item.Id or item.id) ~= nil then
                        local id = tostring(item.Id or item.id)
                        if not control._items[id] then
                            control._items[id] = item
                            control._order[#control._order + 1] = id
                        end
                    end
                end
                local function normalize(value)
                    local out, seen = {}, {}
                    local function add(id)
                        id = tostring(id)
                        if control._items[id] and not seen[id] and not control._items[id].Pinned then
                            seen[id] = true; out[#out + 1] = id
                        end
                    end
                    for _, id in ipairs(type(value) == "table" and value or {}) do add(id) end
                    for _, id in ipairs(control._order) do add(id) end
                    for _, id in ipairs(control._order) do
                        if control._items[id].Pinned then out[#out + 1] = id end
                    end
                    return out
                end
                control.DefaultValue = normalize(options.Default or control._order)
                local function layout()
                    if not root.Parent then return end
                    local width = math.max(80, root.AbsoluteSize.X - 20)
                    local descHeight = description.Text ~= "" and textheight(description.Text, 11, Enum.Font.Gotham, width, 180) or 0
                    description.Visible = descHeight > 0
                    description.Size = UDim2.new(1, -20, 0, descHeight)
                    local y = 29 + (descHeight > 0 and descHeight + 7 or 0)
                    local visible = 0
                    for _, id in ipairs(control.Value) do
                        local row = control.Rows[id]
                        if row and row.Frame.Visible then
                            row.Frame.Position = UDim2.new(0, 7, 0, y)
                            y = y + 51; visible = visible + 1
                        end
                    end
                    empty.Visible = visible == 0
                    empty.Position = UDim2.new(0, 10, 0, y)
                    root.Size = UDim2.new(1, 0, 0, y + (visible == 0 and 23 or 5))
                    queueSectionResize()
                end
                function control:GetValue() return table.clone(self.Value) end
                function control:Set(value, instant)
                    local nextValue = normalize(value)
                    local changed = #nextValue ~= #self.Value
                    for i, id in ipairs(nextValue) do if self.Value[i] ~= id then changed = true end end
                    self.Value = nextValue
                    config.data[key] = table.clone(nextValue)
                    layout()
                    if changed and type(options.Callback) == "function" then
                        local ok, err = pcall(options.Callback, table.clone(nextValue))
                        if not ok then warn("Priority callback error:", err); return false end
                    end
                    return true
                end
                control.SetValue = control.Set
                function control:LoadValue(value) return self:Set(value, true) end
                function control:ResetValue() return self:Set(self.DefaultValue, true) end
                function control:Move(id, delta)
                    id = tostring(id)
                    local at = table.find(self.Value, id)
                    local target = at and at + (delta < 0 and -1 or 1)
                    if not at or not target or not self.Value[target] or self._items[id].Pinned or self._items[self.Value[target]].Pinned then return false end
                    local order = table.clone(self.Value)
                    order[at], order[target] = order[target], order[at]
                    return self:Set(order)
                end
                function control:SetStatus(id, status, sub)
                    local row = self.Rows[tostring(id)]
                    if row then row.Status.Text = tostring(status or "") .. (sub and " · " .. tostring(sub) or "") end
                    return self
                end
                function control:SetVisible(id, visible)
                    if type(id) == "boolean" then root.Visible = id
                    else local row = self.Rows[tostring(id)]; if row then row.Frame.Visible = visible ~= false; layout() end end
                    return self
                end
                for _, id in ipairs(control._order) do
                    local item = control._items[id]
                    local row = instance.frame(root)
                    row.Name = "Task_" .. id; row.Size = UDim2.new(1, -14, 0, 47); row.BorderSizePixel = 0
                    roundbg(row, 4, theme.Inner, true)
                    local label = compatLabel(row, "Title", item.Title or id, 7, 12, true)
                    label.Size = UDim2.new(1, -80, 0, 16)
                    local status = compatLabel(row, "Status", item.Sub or "Ready", 26, 10, false)
                    status.Size = UDim2.new(1, -20, 0, 14)
                    local function moveButton(text, x, delta)
                        local button = instance.textbutton(row)
                        button.Name = delta < 0 and "Up" or "Down"
                        button.Text, button.Font, button.TextSize = text, Enum.Font.GothamBold, 13
                        button.TextColor3 = theme.Text
                        button.Size, button.Position = UDim2.new(0, 25, 0, 24), UDim2.new(1, x, 0, 3)
                        button.Visible = not item.Pinned
                        roundbg(button, 4, theme.ElementHover)
                        button.Activated:Connect(function() control:Move(id, delta) end)
                        return button
                    end
                    control.Rows[id] = {Frame = row, Title = label, Status = status, Up = moveButton("↑", -58, -1), Down = moveButton("↓", -30, 1)}
                end
                watchwidth(root, layout)
                control:Set(config.data[key] or control.DefaultValue, true)
                config.elements[key] = control
                yieldbuild()
                return control
            end
            function items:AddIconGrid(options)
                options = options or {}
                local root, title = compatFrame("IconGrid", options)
                local note = compatLabel(root, "Note", options.Note or "", 29, 11, false)
                local box = instance.frame(root)
                box.Name, box.BackgroundTransparency = "Tiles", 1
                box.Position, box.Size = UDim2.new(0, 7, 0, 48), UDim2.new(1, -14, 0, 0)
                local grid = instance.uigridlayout(box)
                grid.SortOrder, grid.CellPadding = Enum.SortOrder.LayoutOrder, UDim2.new(0, 4, 0, 4)
                local control = {Frame = root, Tiles = {}}
                local maxColumns = math.clamp(math.floor(tonumber(options.Columns) or 4), 1, 6)
                local function layout()
                    if not root.Parent then return end
                    local width = math.max(72, root.AbsoluteSize.X - 14)
                    local columns = math.max(1, math.min(maxColumns, math.floor(width / 70)))
                    grid.CellSize = UDim2.new(1 / columns, -4, 0, 84)
                    local height = math.ceil(#control.Tiles / columns) * 88
                    local y = note.Text == "" and 30 or 48
                    note.Visible = note.Text ~= ""
                    box.Position, box.Size = UDim2.new(0, 7, 0, y), UDim2.new(1, -14, 0, height)
                    root.Size = UDim2.new(1, 0, 0, y + height + 7)
                    queueSectionResize()
                end
                function control:SetNote(value) note.Text = tostring(value or ""); layout(); return self end
                function control:SetVisible(visible) root.Visible = visible ~= false; return self end
                function control:SetItems(values)
                    for _, tile in ipairs(self.Tiles) do tile:Destroy() end
                    self.Tiles = {}
                    for index, item in ipairs(type(values) == "table" and values or {}) do
                        if type(item) == "table" then
                            local tile = instance.frame(box)
                            tile.Name, tile.LayoutOrder, tile.BorderSizePixel = "Tile", index, 0
                            roundbg(tile, 4, theme.Inner, true)
                            local icon = instance.imagelabel(tile)
                            icon.BackgroundTransparency = 1
                            icon.Size, icon.Position = UDim2.new(0, 30, 0, 30), UDim2.new(0.5, -15, 0, 4)
                            icon.ScaleType = Enum.ScaleType.Fit
                            applyicon(icon, item.Icon or "")
                            local name = compatLabel(tile, "Name", item.Name or "", 36, 10, true)
                            name.Position, name.Size = UDim2.new(0, 3, 0, 36), UDim2.new(1, -6, 0, 13)
                            name.TextXAlignment = Enum.TextXAlignment.Center
                            if typeof(item.Color) == "Color3" then name.TextColor3 = item.Color end
                            local value = compatLabel(tile, "Value", tostring(item.Value or ""), 52, 10, true)
                            value.Position, value.Size = UDim2.new(0, 3, 0, 52), UDim2.new(1, -6, 0, 13)
                            value.TextXAlignment = Enum.TextXAlignment.Center
                            local sub = compatLabel(tile, "Sub", item.Sub or "", 67, 9, false)
                            sub.Position, sub.Size = UDim2.new(0, 3, 0, 67), UDim2.new(1, -6, 0, 12)
                            sub.TextXAlignment = Enum.TextXAlignment.Center
                            if typeof(item.SubColor) == "Color3" then sub.TextColor3 = item.SubColor end
                            self.Tiles[#self.Tiles + 1] = tile
                        end
                    end
                    layout(); return self
                end
                watchwidth(root, layout)
                layout(); yieldbuild()
                return control
            end

