    state.TripCharacter = nil
    state.DeliveryPhase = nil
    pcall(performance.setStealing, false)
    state.TargetUid = nil
    semi.SlowRun, semi.AtDrop, semi.Plain = false, false, false
    semi.Kind, semi.Home = nil, nil
    state.Aborting = nil
