	-- Session statistics stay on this device; no account, key or remote commands.
	local state = { started = os.clock(), events = {}, count = 0 }
	function state.noteSteal(record, details)
		if gehleeV4Config.WebMonitoring ~= true or type(record) ~= "table" then return end
		state.count += 1
		if #state.events >= 60 then table.remove(state.events, 1) end
		state.events[#state.events + 1] = {
			name = tostring(type(details) == "table" and details.name or record.AssetCategory or "Egg"),
			at = os.time()
		}
	end
	function state.kick() end
	function state.statusText()
		if gehleeV4Config.WebMonitoring ~= true then return "Off. Enable to count steals in this session." end
		return string.format("Local session: %d steals recorded · %dm elapsed. Nothing is uploaded.", state.count, math.max(0, math.floor((os.clock() - state.started) / 60)))
	end
	return state
end

