        t69.requestManualSteal = function(world, ids)
            local requested, seen = {}, {}
            for _, uid in ipairs(type(ids) == "table" and ids or {}) do
                if type(uid) == "string" and uid ~= "" and not seen[uid] then
                    seen[uid] = true
                    requested[#requested + 1] = uid
                end
            end
            local result = {accepted = {}, rejected = {}, count = 0, reason = "Pick an egg first"}
            if #requested == 0 then return result end
            local ok, count, details
            if world == "Halloween" then
                local queue = genv.__GehleeV4HwQueue
                if type(queue) ~= "function" then result.reason = "Halloween runtime not ready"; return result end
                ok, count = pcall(queue, requested)
                if genv.__GehleeV4HwQueue ~= queue then
                    result.reason = "Halloween runtime changed; try again"
                    return result
                end
                if ok then
                    for _, uid in ipairs(requested) do
                        if t69.manualQueued(world, uid) then result.accepted[uid] = true end
                    end
                end
            else
                local runtime = genv.__GehleeV4EggRuntime
                if not runtime or runtime.destroyed or type(runtime.queueManual) ~= "function" then
                    result.reason = "Runtime not ready; try again"
                    return result
                end
                ok, count, details = pcall(runtime.queueManual, runtime, requested)
                if genv.__GehleeV4EggRuntime ~= runtime or runtime.destroyed then
                    result.reason = "Runtime changed; try again"
                    return result
                end
                if ok and type(details) == "table" then
                    result.accepted = type(details.accepted) == "table" and details.accepted or {}
                    result.rejected = type(details.rejected) == "table" and details.rejected or {}
                    result.reason = tostring(details.reason or "Queued")
                elseif ok then
                    -- Compatibility with older runtimes: total queue size is
                    -- not evidence that this clicked egg was accepted.
                    for _, uid in ipairs(requested) do
                        if t69.manualQueued(world, uid) then result.accepted[uid] = true end
                    end
                end
                local acceptedRequest = false
                for _, uid in ipairs(requested) do
                    if result.accepted[uid] == true then acceptedRequest = true; break end
                end
                if ok and acceptedRequest and tostring(gehleeV4Config.CheckerStealMode) == "Go grab it now"
                    and type(runtime._schedule) == "function" then
                    local scheduled, failure = pcall(runtime._schedule, runtime)
                    if not scheduled then
                        result.reason = "Queued; start delayed, try again"
                        warn("[Gehlee Hub] Manual steal start: " .. tostring(failure))
                    end
