        t69.scan = function(world, rarity, sort)
            world, rarity, sort = world or t69.world, rarity or t69.rarity, sort or t69.sort
            if world == "Halloween" then
                local ok, rows = pcall(t69.scanHw, rarity)
                return ok and type(rows) == "table" and rows or {}
            end
            local read, snapshot = pcall(obj.ReadFieldEggs)
            if not read or type(snapshot) ~= "table" or type(snapshot.Records) ~= "table" then return {} end
            local rows, seen = {}, {}
            local function finite(value, fallback)
                value = tonumber(value)
                if value == nil or value ~= value or math.abs(value) == math.huge then return fallback end
                return value
            end
            for _, record in pairs(snapshot.Records) do
                if type(record) == "table" and type(record.Uid) == "string" and record.Uid ~= ""
                    and not seen[record.Uid] and not record.Uid:find("FirstAreaEgg", 1, true)
                    and (record.State == "Slot" or record.State == "Dropped") and not record.CarrierUserId
                    and typeof(record.BottomCFrame) == "CFrame" then
                    -- One unfinished asset must not remove every healthy row.
                    local ok, row = pcall(function()
                        local category = record.AssetCategory
                        local asset = category and Assets.Directory and Assets.Directory[category]
                        local rank, rarity, color = v6145(category)
                        local scale = finite(record.AssetScale or record.Scale, 1)
                        local metadata = {AssetCategory=category, Category=category, AssetScale=scale,
                            Scale=scale, Mutations=type(record.Mutations)=="table" and record.Mutations or {}}
                        return {rec=record, uid=record.Uid, name=tostring((asset and asset.DisplayName) or category or "Egg"),
                            rarity=tostring(rarity or "?"), rnum=finite(rank,0), color=color,
                            area=tostring(record.AreaId or "?"), rate=finite(v6177(metadata),0),
                            kg=finite(v6180(record),nil), scale=scale, icon=v6148(category)}
                    end)
                    if ok and (rarity == "All" or row.rarity == rarity) then
                        seen[record.Uid] = true
                        rows[#rows+1] = row
                    end
                end
            end
            table.sort(rows, function(a,b)
                if sort == "weight" then
                    if (a.kg or 0) ~= (b.kg or 0) then return (a.kg or 0) > (b.kg or 0) end
                    return a.rate > b.rate
                end
                if sort == "rarity" then
                    if a.rnum ~= b.rnum then return a.rnum > b.rnum end
                    return a.rate > b.rate
                end
                if a.rate ~= b.rate then return a.rate > b.rate end
                return a.rnum > b.rnum
            end)
            return rows
        end
