local finderModules = {}
local function finderModule(path)
    if finderModules[path] then return finderModules[path] end
    local object = ReplicatedStorage3
    for name in string.gmatch(path, "[^/]+") do
        object = object and object:FindFirstChild(name)
    end
    if not object then return nil end
    local ok, value = pcall(require, object)
    if ok and type(value) == "table" then
        finderModules[path] = value
        return value
    end
    return nil
end
local function finderNumber(value)
    local number = tonumber(value)
    return number and number == number and number >= 0 and number < math.huge and number or 0
end
local function finderRarity(value)
    if type(value) == "table" then value = value.DisplayName or value._id or value.Name end
    return type(value) == "string" and value or "Unknown"
end
local function finderNormalize(value)
    return tostring(value or ""):lower():gsub("[%s_%-]", ""):gsub("egg$", "")
end
