    if type(value) == "table" then
        for _, name in ipairs(value) do
            if table.find(finderDefaultCats, name) then picked[name] = true; any = true end
        end
    end
    if not any then
        for _, name in ipairs(finderDefaultCats) do picked[name] = true end
